import sqlite3

def pedidos_relevantes():
    conexao = sqlite3.connect(':memory:')
    cursor = conexao.cursor()
    cursor.execute('CREATE TABLE pedidos (id INTEGER PRIMARY KEY, cliente TEXT, valor REAL)')
    cursor.executemany(
        'INSERT INTO pedidos (cliente, valor) VALUES (?, ?)',
        [('Ana', 40), ('Bia', 120), ('Carlos', 90), ('Duda', 160), ('Elo', 80)]
    )
    conexao.commit()
    return cursor.execute(
        'SELECT cliente, valor FROM pedidos WHERE valor >= 90 ORDER BY valor DESC LIMIT 2'
    ).fetchall()
